def remise(montant):
    if montant >= 50000:
        return montant * 10 // 100
    if montant >= 10000:
        return montant * 5 // 100
    return 0

CAS = [
    (9999, 0),
    (10000, 500),
    (49999, 2499),
    (50000, 5000),
]


def test_remise():
    for montant, attendu in CAS:
        assert remise(montant) == attendu, (montant, remise(montant), attendu)


test_remise()
print(len(CAS), "cas vérifiés")

def remise(montant):
    return montant * 5 // 100


CAS = [(9999, 0), (10000, 500)]
try:
    for montant, attendu in CAS:
        assert remise(montant) == attendu, (montant, remise(montant), attendu)
except AssertionError as e:
    print("Échec :", e)

