def remise(montant):
    if montant >= 50000:
        return montant * 10 // 100
    if montant >= 10000:
        return montant * 5 // 100
    return 0

CAS = [
    (20000, 1000),
]


def test_remise():
    for montant, attendu in CAS:
        assert remise(montant) == attendu, (montant, remise(montant), attendu)


# Vérification fournie : ne la modifie pas.
MUTANTS = [
    lambda m: m * 10 // 100 if m > 50000 else (m * 5 // 100 if m >= 10000 else 0),
    lambda m: m * 10 // 100 if m >= 50000 else (m * 5 // 100 if m > 10000 else 0),
    lambda m: m * 5 // 100 if m >= 10000 else 0,
    lambda m: 0,
]


def evaluer_tests():
    global remise
    original = remise
    test_remise()
    resultats = []
    for mutant in MUTANTS:
        remise = mutant
        try:
            test_remise()
            resultats.append("raté")
        except Exception:
            resultats.append("détecté")
    remise = original
    return resultats

